const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const filtered = $input.all()
  .filter(item => {
    const d = new Date(item.json.pubDate || item.json.isoDate || 0);
    return !isNaN(d.getTime()) && d > sevenDaysAgo;
  })
  .map(item => ({
    title: String(item.json.title || '').trim(),
    link: String(item.json.link || ''),
    contentSnippet: String(item.json.contentSnippet || item.json.content || '').slice(0, 400).trim()
  }));

const articlesText = filtered.length > 0
  ? filtered.map(i => 'Title: ' + i.title + '\nURL: ' + i.link + '\nSnippet: ' + i.contentSnippet).join('\n\n---\n\n')
  : 'No articles found this week. Generate placeholder content for a workflow-automation themed issue.';

return [{ json: { itemCount: filtered.length, articlesText } }];

const output = $input.first().json.output;
if (!output) throw new Error('No output from AI agent');
let parsed;
try {
  const cleaned = output.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Failed to parse agent JSON: ' + e.message + '. Output was: ' + String(output).slice(0, 300));
}
const si = parsed.signal_items || [];
const so = parsed.subject_options || ['StackSignal Draft', 'StackSignal Draft', 'StackSignal Draft'];
const theme = parsed.theme || 'workflow-automation';

// signal_items text originates from RSS feed content by way of the AI agent — treat it as
// untrusted and escape before embedding in HTML that becomes the newsletter draft body.
function escapeHtml(str) {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function sanitizeUrl(str) {
  // Blocks javascript:/data: URI XSS — escapeHtml alone can't neutralize a dangerous scheme.
  const s = String(str || '').trim();
  return /^https?:\/\//i.test(s) ? s : '#';
}

const signalHtml = si.map(i => {
  const title = escapeHtml(i.title);
  const url = escapeHtml(sanitizeUrl(i.url));
  const take = escapeHtml(i.take);
  return '<p><strong>' + title + '</strong> — <a href="' + url + '">' + url + '</a><br><em>' + take + '</em></p>';
}).join('\n');
const content = '<h2>⚙️ THE WORKFLOW</h2>\n<p>[Draft here — 550–650 words]</p>\n<hr>\n<h2>🔧 THE STACK MOVE</h2>\n<p>[Draft here — 220–270 words]</p>\n<hr>\n<h2>📡 THE SIGNAL</h2>\n' + signalHtml;
const discordMessage = '📝 **StackSignal draft ready**\n\n**Theme:** ' + theme + '\n\n**Subject options:**\n1. ' + so[0] + '\n2. ' + so[1] + '\n3. ' + so[2] + '\n\n**Signal items:** ' + si.length + ' pre-populated\n\n→ Open Beehiiv to write Workflow + Stack Move sections';
return [{ json: { signal_items: si, subject_options: so, theme, beehiivTitle: so[0] + ' [DRAFT]', beehiivSubtitle: 'Theme: ' + theme + ' | Options: ' + so.join(' / '), beehiivContent: content, discordMessage } }];

const crypto = require('crypto');
const parsed = $input.first().json;
const so = parsed.subject_options || ['', '', ''];
const si = parsed.signal_items || [];
const theme = parsed.theme || '';
const guid = crypto.randomUUID();
const pubDate = new Date().toISOString();
const discordMessage = `📝 **StackSignal draft queued in RSS feed**

**Theme:** ${theme}

**Subject options:**
1. ${so[0]}
2. ${so[1]}
3. ${so[2]}

**Signal items:** ${si.length} pre-populated

→ Beehiiv picks it up within the hour. Open Beehiiv to write Workflow + Stack Move sections.`;
return [{ json: { ...parsed, rss_guid: guid, rss_pub_date: pubDate, rss_title: parsed.beehiivTitle, rss_body_html: parsed.beehiivContent, discordMessage } }];
